$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
function RoundPath([float]$x,[float]$y,[float]$w,[float]$h,[float]$r){$p=New-Object System.Drawing.Drawing2D.GraphicsPath;$d=[math]::Min($r*2,[math]::Min($w,$h));$p.AddArc($x,$y,$d,$d,180,90);$p.AddArc($x+$w-$d,$y,$d,$d,270,90);$p.AddArc($x+$w-$d,$y+$h-$d,$d,$d,0,90);$p.AddArc($x,$y+$h-$d,$d,$d,90,90);$p.CloseFigure();$p}
function FillRR($g,$b,[float]$x,[float]$y,[float]$w,[float]$h,[float]$r){$p=RoundPath $x $y $w $h $r;try{$g.FillPath($b,$p)}finally{$p.Dispose()}}
function DrawRR($g,$p,[float]$x,[float]$y,[float]$w,[float]$h,[float]$r){$path=RoundPath $x $y $w $h $r;try{$g.DrawPath($p,$path)}finally{$path.Dispose()}}
function TF([System.Drawing.StringAlignment]$a=[System.Drawing.StringAlignment]::Near,[System.Drawing.StringAlignment]$l=[System.Drawing.StringAlignment]::Near){$f=New-Object System.Drawing.StringFormat;$f.Alignment=$a;$f.LineAlignment=$l;$f}
function T($g,[string]$t,$fnt,$b,[float]$x,[float]$y,[float]$w,[float]$h,[System.Drawing.StringAlignment]$a=[System.Drawing.StringAlignment]::Near,[System.Drawing.StringAlignment]$l=[System.Drawing.StringAlignment]::Near){$r=New-Object System.Drawing.RectangleF([single]$x,[single]$y,[single]$w,[single]$h);$fmt=TF $a $l;try{$g.DrawString($t,$fnt,$b,$r,$fmt)}finally{$fmt.Dispose()}}
function Card($g,[float]$x,[float]$y,[float]$w,[float]$h,$fill,$pen){FillRR $g $fill $x $y $w $h 18;if($pen){DrawRR $g $pen $x $y $w $h 18}}
function Pill($g,[string]$t,[float]$x,[float]$y,[float]$w,[float]$h,$fill,$b,$fnt){FillRR $g $fill $x $y $w $h 999;T $g $t $fnt $b $x $y $w $h ([System.Drawing.StringAlignment]::Center) ([System.Drawing.StringAlignment]::Center)}
function NewPage(){ $bmp=New-Object System.Drawing.Bitmap 1240,1754; $g=[System.Drawing.Graphics]::FromImage($bmp); $g.Clear([System.Drawing.Color]::White); $g.SmoothingMode=[System.Drawing.Drawing2D.SmoothingMode]::AntiAlias; $g.TextRenderingHint=[System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit; @{Bitmap=$bmp;Graphics=$g} }
function SavePage($page,[string]$path){ $page.Bitmap.Save($path,[System.Drawing.Imaging.ImageFormat]::Jpeg); $page.Graphics.Dispose(); $page.Bitmap.Dispose() }
